SourceCode.Declaration:
/// <summary>
/// Retries the retriable SOs of a prior extraction run via a single Class1 retry-parent
/// task, without touching lines already Completed.
/// </summary>
class METSalesOrderExtractionRetryService
{
}

Method.Source:
/// <summary>
/// True if the extraction has a Failed line, or (with no Failed line - every SO already
/// Completed) the header itself is Failed, meaning only the End task needs retrying.
/// </summary>
/// <param name = "_extractionId">Extraction to check</param>
/// <returns>True if a retry is possible</returns>
public static boolean canRetry(METSalesOrderExtractionId _extractionId)
{
    METSalesOrderExtractionLine   extractionLine;
    METSalesOrderExtractionTable  header;
    boolean                       hasFailedLines;

    if (_extractionId)
    {
        select firstonly RecId from extractionLine
           where extractionLine.ExtractionId     == _extractionId
              && extractionLine.ExtractionStatus  == METSalesOrderExtractionStatus::Failed;

        hasFailedLines = extractionLine.RecId != 0;

        if (!hasFailedLines)
        {
            select firstonly ExtractionStatus from header
                where header.ExtractionId == _extractionId;

            return header.ExtractionStatus == METSalesOrderExtractionStatus::Failed;
        }
    }

    return hasFailedLines;
}

/// <summary>
/// Retries retriable lines if any exist (full Phase1+Phase2 retry); otherwise, if the
/// header itself is Failed, resumes only the End/CSD tasks.
/// </summary>
/// <param name = "_extractionId">Extraction to retry</param>
public static void retry(METSalesOrderExtractionId _extractionId)
{
    METSalesOrderExtractionTable header = METSalesOrderExtractionTable::find(_extractionId);
    container                    retriableSalesIds;

    if (!header.RecId)
    {
        throw error(strFmt("@MET:METExtractionNotFound", _extractionId));
    }

    retriableSalesIds = METSalesOrderExtractionRetryService::getRetriableSalesIds(_extractionId);

    if (conLen(retriableSalesIds) > 0)
    {
        METSalesOrderExtractionRetryService::resetRetriableLines(_extractionId, retriableSalesIds);
        METSalesOrderExtractionRetryService::spawnRetryBatch(header, retriableSalesIds);
        info(strFmt("@MET:METRetryScheduled", conLen(retriableSalesIds), _extractionId));
    }
    else if (header.ExtractionStatus == METSalesOrderExtractionStatus::Failed)
    {
        METSalesOrderExtractionRetryService::resetHeaderForFinalTaskRetry(_extractionId);
        METSalesOrderExtractionRetryService::spawnFinalTaskRetryBatch(header);
        info(strFmt("@MET:METFinalTaskRetryScheduled", _extractionId));
    }
    else
    {
        warning("@MET:METNoFailedLinesToRetry");
    }
}

/// <summary>
/// Failed lines, plus - once at least one line has Failed - every still-Processing
/// sibling too (a Processing line is just as stuck, it just never errored itself).
/// </summary>
/// <param name = "_extractionId">Extraction to scan</param>
/// <returns>Container of retriable SalesIds</returns>
private static container getRetriableSalesIds(METSalesOrderExtractionId _extractionId)
{
    METSalesOrderExtractionLine extractionLine;
    container                   retriableSalesIds;
    boolean                     hasFailedLine;

    while select SalesId, ExtractionStatus from extractionLine
        where extractionLine.ExtractionId     == _extractionId
           && (extractionLine.ExtractionStatus == METSalesOrderExtractionStatus::Failed
            || extractionLine.ExtractionStatus == METSalesOrderExtractionStatus::Processing)
    {
        if (extractionLine.ExtractionStatus == METSalesOrderExtractionStatus::Failed)
        {
            hasFailedLine = true;
        }

        retriableSalesIds += extractionLine.SalesId;
    }

    return hasFailedLine ? retriableSalesIds : conNull();
}

/// <summary>
/// Resets every retried line back to Pending, bumps RetryCount, and clears ErrorMessage.
/// </summary>
/// <param name = "_extractionId">Owning ExtractionId</param>
/// <param name = "_retriableSalesIds">SalesIds to reset</param>
private static void resetRetriableLines(METSalesOrderExtractionId _extractionId, container _retriableSalesIds)
{
    int i;

    ttsbegin;

    for (i = 1; i <= conLen(_retriableSalesIds); i++)
    {
        METSalesOrderExtractionLine extractionLine = METSalesOrderExtractionLine::find(_extractionId, conPeek(_retriableSalesIds, i), true);

        if (extractionLine.RecId)
        {
            extractionLine.ExtractionStatus = METSalesOrderExtractionStatus::Pending;
            extractionLine.RetryCount       += 1;
            extractionLine.ErrorMessage      = '';
            extractionLine.update();
        }
    }

    ttscommit;
}

/// <summary>
/// Resets the header back to Processing and clears ErrorMessage before resuming only
/// the End/CSD tasks.
/// </summary>
/// <param name = "_extractionId">Extraction to reset</param>
private static void resetHeaderForFinalTaskRetry(METSalesOrderExtractionId _extractionId)
{
    METSalesOrderExtractionTable header;

    ttsbegin;

    header = METSalesOrderExtractionTable::find(_extractionId, true);

    if (header.RecId)
    {
        header.ExtractionStatus = METSalesOrderExtractionStatus::Processing;
        header.ErrorMessage     = '';
        header.update();
    }

    ttscommit;
}

/// <summary>
/// Schedules a Class1 retry-parent task that reruns Phase1+Phase2 for the given SalesIds.
/// </summary>
/// <param name = "_header">The extraction header, carrying the persisted CSD/shipment context</param>
/// <param name = "_retriedSalesIds">SalesIds to retry</param>
private static void spawnRetryBatch(METSalesOrderExtractionTable _header, container _retriedSalesIds)
{
    METSalesPickingListReservationBatch retryParentTask = METSalesPickingListReservationBatch::constructForRetry(_header.ExtractionId, _retriedSalesIds, _header);

    METSalesOrderExtractionRetryService::scheduleRetryParentTask(retryParentTask, _header.ExtractionId);
}

/// <summary>
/// Schedules a Class1 retry-parent task that resumes only the End/CSD tasks - every
/// per-SO task already Completed.
/// </summary>
/// <param name = "_header">The extraction header, carrying the persisted CSD/shipment context</param>
private static void spawnFinalTaskRetryBatch(METSalesOrderExtractionTable _header)
{
    METSalesPickingListReservationBatch retryParentTask = METSalesPickingListReservationBatch::constructForFinalTaskRetry(_header.ExtractionId, _header);

    METSalesOrderExtractionRetryService::scheduleRetryParentTask(retryParentTask, _header.ExtractionId);
}

/// <summary>
/// Shared scheduling for both retry shapes: new job, same caption/group as a fresh run.
/// </summary>
/// <param name = "_retryParentTask">The configured retry-parent task to schedule</param>
/// <param name = "_extractionId">Owning ExtractionId, for the job caption</param>
private static void scheduleRetryParentTask(METSalesPickingListReservationBatch _retryParentTask, METSalesOrderExtractionId _extractionId)
{
    METCustParameters  metCustParameters = METCustParameters::find();
    BatchHeader        retryBatchHeader  = BatchHeader::construct();

    retryBatchHeader.parmCaption(strFmt("@MET:METCaptionReservationSetupForExtraction", "@MET:MetPickingListGeneration", curUserId(), _extractionId));

    _retryParentTask.batchInfo().resetBatchHeader();

    if (metCustParameters.SalesExtractionBatchGroupId)
    {
        _retryParentTask.batchInfo().parmGroupId(metCustParameters.SalesExtractionBatchGroupId);
    }

    _retryParentTask.batchInfo().parmConstraintType(BatchConstraintType::And);
    _retryParentTask.batchInfo().parmDataareaId(curExt());

    retryBatchHeader.addTask(_retryParentTask);
    retryBatchHeader.save();
}
